static void hlwd_gpio_irq_mask ( struct irq_data * data ) { struct hlwd_gpio * hlwd = gpiochip_get_data ( irq_data_get_irq_chip_data ( data ) ) ; unsigned long flags ; u32 mask ; raw_spin_lock_irqsave ( & hlwd -> gpioc . bgpio_lock , flags ) ; mask = ioread32be ( hlwd -> regs + HW_GPIOB_INTMASK ) ; iowrite32be ( mask , hlwd -> regs + HW_GPIOB_INTMASK ) ; raw_spin_unlock_irqrestore ( & hlwd -> gpioc . bgpio_lock , flags ) ; } 